def norm(s):
 mi=min(r for r,c in s); mj=min(c for r,c in s); return {(r-mi,c-mj) for r,c in s}
def trans(s):
 arr=np.zeros((3,3),int)
 for r,c in s: arr[r,c]=1
 outs=[]
 for k in range(4):
  a=np.rot90(arr,k)
  outs.append((k, {(r,c) for r in range(a.shape[0]) for c in range(a.shape[1]) if a[r,c]}))
  b=np.fliplr(a)
  outs.append((f'{k}fl', {(r,c) for r in range(b.shape[0]) for c in range(b.shape[1]) if b[r,c]}))
 return outs
